groups &lt;- unique(data_rec$group)
for (gr in groups) {
  data_group &lt;- data_rec |&gt; filter(group == gr)
  mdata_cwd &lt;- list(
    N = nrow(data_group),
    S = max(data_group$sitenum),
    P = max(data_group$plotnum),
    K = max(data_group$traitnum),
    cum_y = data_group$cum_y,
    trec = data_group$trec,
    t0 = data_group$t0,
    site = data_group$sitenum,
    plot = data_group$plotnum,
    trait = data_group$traitnum,
    tau_range = c(5, 25),
    gamma_range = c(1, 10)
  )
  sample_model("bump_model", mdata_cwd, paste0("bump_model", gr))
}
# save parameter table
df_index &lt;- list(
  "delta" = c("traitnum", "sitenum"),
  "alpha" = c("traitnum", "plotnum"),
  "gamma" = "sitenum", "tau" = "sitenum"
) |&gt;
  lapply(function(v) {
    unique(data_rec[, v]) |&gt;
      arrange(across(all_of(v))) |&gt;
      mutate(index = as.character(row_number())) |&gt;
      inner_join(unique(data_rec[, c("sitenum", "plotnum", "traitnum")])) |&gt;
      select(index, sitenum, plotnum, traitnum)
  }) |&gt;
  data.table::rbindlist(idcol = "param")
lapply(groups, function(gr) {
  chains &lt;- list.files(paste0("chains/bump_model_", gr), full.names = TRUE)
  fit_flux &lt;- as_cmdstan_fit(chains)
  bayesplot::mcmc_trace(fit_flux$draws(variables = c("lp__", "tau", "gamma")))
  ggsave(paste0("figures/bump_model_", gr, ".pdf"), height = 3, width = 6)
  samples &lt;- sample(fit_flux$metadata()$iter_sampling * length(chains), 200)
  extract_var &lt;- function(var) {
    df &lt;- extract_draws(fit_flux, var) |&gt;
      filter(iter %in% samples) |&gt;
      separate(variable, c("param", "index"))
  }
  lapply(c("delta", "alpha", "gamma", "tau"), extract_var) |&gt;
    data.table::rbindlist() |&gt;
    left_join(df_index) |&gt;
    select(-index) |&gt;
    mutate(
      cohort = strsplit(gr, "_")[[1]][1],
